// SQ_COMMENT_API_V1_BEGIN
var SQ_COMMENT_API_BASE = "https://shuqi.aadcn.cn";
var SQ_COMMENT_API_KEY = "djiaofanfuwafiowanifuhafn";
var _sqRenderExtKey = "";
var _sqRenderExtValue = null;
var _sqMetaMapCache = null;
var _sqShortMapCache = null;

function sqSource() {
    try { if (this && this.source) return this.source; } catch(e) {}
    try { if (typeof source !== "undefined") return source; } catch(e2) {}
    return null;
}

function sqJava() {
    try { if (this && this.java) return this.java; } catch(e) {}
    try { if (typeof java !== "undefined") return java; } catch(e2) {}
    return null;
}

function sqLoginValue(key, defaultValue) {
    try {
        var s = sqSource.call(this);
        var map = s && s.getLoginInfoMap ? s.getLoginInfoMap() : null;
        var value = map && (map.get ? map.get(key) : map[key]);
        if (value !== null && value !== undefined && String(value).trim() !== "") return String(value);
    } catch(e) {}
    return defaultValue == null ? "" : String(defaultValue);
}

function sqToggle(key, defaultValue) {
    var value = sqLoginValue.call(this, key, "");
    if (!value) return !!defaultValue;
    value = String(value).trim().toLowerCase();
    return value === "✅" || value === "1" || value === "true" || value === "开" || value === "开启";
}

function sqCommentConfig() {
    var style = sqLoginValue.call(this, "◎ 模板", "起点");
    var templateKey = String(style).replace("样式", "◎ 气泡");
    return {
        paragraph: sqToggle.call(this, "段评开关", false),
        chapter: sqToggle.call(this, "章评开关", false),
        color: sqLoginValue.call(this, "段评气泡颜色", "#666666"),
        colorSplit: sqToggle.call(this, "段评分色", false),
        splitColor: sqLoginValue.call(this, "分色气泡颜色", "#e23b3b"),
        splitCount: Number(sqLoginValue.call(this, "分色评论数", "45")) || 45,
        hotColor: sqLoginValue.call(this, "热门气泡颜色", "#f06060"),
        theme: sqLoginValue.call(this, "评论主题", "自动"),
        height: sqLoginValue.call(this, "评论窗口高度", "80"),
        bubbleStyle: style,
        bubbleSize: sqLoginValue.call(this, "◎ 大小", "text"),
        bubbleTemplate: sqLoginValue.call(this, templateKey, "")
    };
}

function sqApiKey() {
    return sqLoginValue.call(this, "书旗评论 API Key", "") || SQ_COMMENT_API_KEY;
}

function sqPost(path, body) {
    var j = sqJava.call(this);
    if (!j) return { ok: false, error: "java unavailable" };
    var payload = body || {};
    payload.apiKey = sqApiKey.call(this);
    var option = {
        method: "POST",
        body: JSON.stringify(payload),
        headers: { "Content-Type": "application/json", "Accept": "application/json" }
    };
    try {
        var raw = j.ajax(SQ_COMMENT_API_BASE + path + "," + JSON.stringify(option));
        var text = String(raw || "{}").replace(/^\uFEFF/, "").trim();
        return JSON.parse(text || "{}");
    } catch(e) {
        try { j.log("书旗评论接口请求失败 " + path + ": " + e); } catch(_) {}
        return { ok: false, error: String(e) };
    }
}

function sqList(value) {
    if (!value) return [];
    if (Array.isArray(value)) return value;
    if (value.size && value.get) {
        var result = [];
        for (var i = 0; i < value.size(); i++) result.push(value.get(i));
        return result;
    }
    return [];
}

function sqRenderExt(bookId, chapterId) {
    var key = String(bookId || "") + ":" + String(chapterId || "");
    if (key && key === _sqRenderExtKey && _sqRenderExtValue) return _sqRenderExtValue;
    var response = sqPost.call(this, "/v1/reader/render-ext", {
        bookId: String(bookId || ""),
        chapterId: String(chapterId || "")
    });
    if (response && response.ok) {
        _sqRenderExtKey = key;
        _sqRenderExtValue = response;
    }
    return response || { ok: false };
}

function sqParagraphList(response) {
    try {
        var outer = response && response.data || {};
        var data = outer.data || outer.Data || {};
        var ext = data.bookChapterExtInfo || data.BookChapterExtInfo || {};
        return sqList(ext.paragraphList || ext.ParagraphList);
    } catch(e) {
        return [];
    }
}

function sqCommentList(response) {
    try {
        var outer = response && response.data || {};
        var data = outer.data || outer.Data || {};
        return sqList(data.commentList || data.CommentList);
    } catch(e) {
        return [];
    }
}

function sqReadMap(key, cacheName) {
    if (cacheName === "meta" && _sqMetaMapCache !== null) return _sqMetaMapCache;
    if (cacheName === "short" && _sqShortMapCache !== null) return _sqShortMapCache;
    var map = {};
    try {
        var j = sqJava.call(this);
        var raw = j && j.get ? j.get(key) : "";
        if (raw) map = JSON.parse(String(raw)) || {};
    } catch(e) { map = {}; }
    if (cacheName === "meta") _sqMetaMapCache = map;
    if (cacheName === "short") _sqShortMapCache = map;
    return map;
}

function sqLookupChapterMap(map, url) {
    map = map || {};
    var raw = String(url || "");
    var optionAt = raw.lastIndexOf(",{");
    if (optionAt > 0) raw = raw.substring(0, optionAt);
    var candidates = [raw];
    var queryAt = raw.indexOf("?");
    if (queryAt >= 0) candidates.push(raw.substring(queryAt));
    var count = candidates.length;
    for (var i = 0; i < count; i++) {
        candidates.push(candidates[i].replace(/0$/, "1"));
        candidates.push(candidates[i].replace(/1$/, "0"));
    }
    for (var j = 0; j < candidates.length; j++) {
        if (Object.prototype.hasOwnProperty.call(map, candidates[j])) return map[candidates[j]];
    }
    return null;
}

function sqGetShortMap(ctx) {
    return sqReadMap.call(ctx || this, "sqShortMap", "short");
}

function sqLookupMap(map, base) {
    var value = sqLookupChapterMap(map, base);
    return value == null ? "" : String(value);
}

function sqGetChapterMeta(url) {
    var raw = String(url || "");
    try {
        var bidMatch = raw.match(/[#&?]sqBid=([^&#]+)/);
        var cidMatch = raw.match(/[#&?]sqCid=([^&#]+)/);
        if (bidMatch && cidMatch) {
            return {
                bookId: decodeURIComponent(bidMatch[1]),
                chapterId: decodeURIComponent(cidMatch[1])
            };
        }
    } catch(eHash) {}
    var value = sqLookupChapterMap(sqReadMap.call(this, "sqMetaMap", "meta"), raw);
    if (!value) return null;
    if (typeof value === "string") {
        try { value = JSON.parse(value); } catch(e) { return null; }
    }
    return value && value.bookId && value.chapterId ? value : null;
}

function sqGetChapterShortUrl(url) {
    var value = sqLookupChapterMap(sqReadMap.call(this, "sqShortMap", "short"), url);
    return value == null ? "" : String(value);
}

function sqSafeJs(value) {
    return String(value == null ? "" : value)
        .replace(/\\/g, "\\\\").replace(/'/g, "\\'").replace(/[\r\n]+/g, "");
}

function sqQuoteText(value) {
    var text = String(value == null ? "" : value)
        .replace(/<br\s*\/?>(?=.)/gi, "\n")
        .replace(/<img\b[^>]*>/gi, "")
        .replace(/<[^>]+>/g, "")
        .replace(/&nbsp;/gi, " ")
        .replace(/&amp;/gi, "&")
        .replace(/&quot;/gi, '"')
        .replace(/&#39;/gi, "'")
        .replace(/&lt;/gi, "<")
        .replace(/&gt;/gi, ">")
        .replace(/[\s\u00a0\u3000]+/g, " ")
        .trim();
    if (text.length > 160) text = text.slice(0, 160) + "…";
    return text;
}
function sqBubbleData(count, bookId, chapterId, paragraphId, hot, kind, paraText) {
    var j = sqJava.call(this);
    var number = Number(count) || 0;
    if (!j || !j.base64Encode || number <= 0) return "";
    var cfg = sqCommentConfig.call(this);
    var color = cfg.color;
    if (cfg.colorSplit) {
        if (hot) color = cfg.hotColor;
        else if (number >= cfg.splitCount) color = cfg.splitColor;
    }
    if (!/^#[0-9a-fA-F]{6}$/.test(color)) color = "#666666";
    var displayText = number > 999 ? "999" : String(number);
    var font = "Arial";
    var template = String(cfg.bubbleTemplate || "").trim();
    var svg;
    if (cfg.bubbleStyle !== "起点" && template.indexOf("<svg") >= 0) {
        svg = template
            .replace(/\$\{qpyscolor\}/g, color)
            .replace(/\$\{qpwzcolor\}/g, color)
            .replace(/\$\{font\}/g, font)
            .replace(/\$\{displayText\}/g, displayText);
    } else {
        svg = '<svg viewBox="5 14 45 36" xmlns="http://www.w3.org/2000/svg" width="180" height="144">' +
            '<path d="M44 48 Q48 48 48 44 L48 20 Q48 16 44 16 L20 16 Q16 16 16 20 L16 24 S16 28 10 30 Q6 32 10 34 Q16 36 16 38 L16 44 Q16 48 20 48 Z" fill="none" stroke="' + color + '" stroke-width="0.7"/>' +
            '<text x="32" y="38" text-anchor="middle" font-family="' + font + '" font-weight="600" font-size="18" fill="' + color + '" dominant-baseline="middle">' + displayText + '</text>' +
            '</svg>';
    }
    var click;
    if (kind === "chapter") {
        click = "showSqChapterComments('" + sqSafeJs(bookId) + "','" + sqSafeJs(chapterId) + "','" + sqSafeJs(paragraphId) + "','" + sqSafeJs(sqQuoteText(paraText)) + "')";
    } else {
        click = "showSqComments('" + sqSafeJs(bookId) + "','" + sqSafeJs(chapterId) + "','" + sqSafeJs(paragraphId) + "','" + sqSafeJs(sqQuoteText(paraText)) + "')";
    }
    return "data:image/svg+xml;base64," + j.base64Encode(svg) + "," + JSON.stringify({
        style: cfg.bubbleSize === "TEXT" ? "TEXT" : "text",
        type: "sq",
        click: click
    });
}

function sqBubbleImage(count, bookId, chapterId, paragraphId, hot, paraText) {
    var data = sqBubbleData.call(this, count, bookId, chapterId, paragraphId, hot, "paragraph", paraText);
    return data ? '<img src="' + data.replace(/"/g, "&quot;") + '">' : "";
}

function sqDecorateContent(content, bookId, chapterId, chapterTitle) {
    var cfg = sqCommentConfig.call(this);
    var sourceRef = sqSource.call(this);
    var titleKey = "sq_title_bubble_" + String(chapterId || "");
    function saveTitle(value) {
        try { if (sourceRef && sourceRef.put && chapterId) sourceRef.put(titleKey, String(value || "")); } catch(e) {}
    }
    if ((!cfg.paragraph && !cfg.chapter) || !bookId || !chapterId) {
        saveTitle("");
        return content;
    }

    var response = sqRenderExt.call(this, bookId, chapterId);
    var paragraphs = sqParagraphList(response);
    if (!paragraphs.length) {
        saveTitle("");
        return content;
    }

    var titleItem = null;
    var bodyItems = [];
    for (var p = 0; p < paragraphs.length; p++) {
        var item = paragraphs[p] || {};
        var order = Number(item.orderId !== undefined ? item.orderId : item.OrderId);
        var count = Number(item.commentCount || item.CommentCount || 0);
        if (count <= 0) continue;
        if (order === 0) titleItem = item;
        else if (order > 0) bodyItems.push(item);
    }

    if (cfg.chapter && titleItem) {
        var titleCount = Number(titleItem.commentCount || titleItem.CommentCount || 0);
        var titlePid = titleItem.paragraphId || titleItem.ParagraphId || "p000";
        var titleText = String(titleItem.text || titleItem.Text || titleItem.summaryText || titleItem.SummaryText || chapterTitle || "");
        saveTitle(sqBubbleData.call(this, titleCount, bookId, chapterId, titlePid, !!(titleItem.isHotParagraph || titleItem.IsHotParagraph), "chapter", titleText));
    } else {
        saveTitle("");
    }
    if (!cfg.paragraph) return content;

    var pieces = String(content || "").split(/(<br\s*\/?>)/i);
    var textIndexes = [];
    for (var i = 0; i < pieces.length; i++) {
        if (!/^<br\s*\/?>$/i.test(pieces[i]) && String(pieces[i]).trim()) textIndexes.push(i);
    }
    for (var b = 0; b < bodyItems.length; b++) {
        var bodyItem = bodyItems[b] || {};
        var bodyOrder = Number(bodyItem.orderId !== undefined ? bodyItem.orderId : bodyItem.OrderId);
        var bodyCount = Number(bodyItem.commentCount || bodyItem.CommentCount || 0);
        var bodyPid = bodyItem.paragraphId || bodyItem.ParagraphId || ("p" + String(bodyOrder));
        var target = textIndexes[bodyOrder - 1];
        if (target !== undefined) {
            var bodyText = String(bodyItem.text || bodyItem.Text || bodyItem.summaryText || bodyItem.SummaryText || pieces[target] || "");
            pieces[target] += sqBubbleImage.call(this, bodyCount, bookId, chapterId, bodyPid, !!(bodyItem.isHotParagraph || bodyItem.IsHotParagraph), bodyText);
        }
    }
    return pieces.join("");
}

function sqEscapeHtml(value) {
    return String(value == null ? "" : value)
        .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

function sqRichText(comment) {
    var raw = String(comment && (comment.richText || comment.text) || "");
    var images = [];
    raw = raw.replace(/<img\b[^>]*>/gi, function(tag) {
        var match = tag.match(/src=["'](data:image\/(?:webp|png|gif);base64,[A-Za-z0-9+/=]+)["']/i);
        if (!match) return "";
        var token = "__SQ_EMOJI_" + images.length + "__";
        images.push('<img class="emoji" src="' + match[1] + '" alt="">');
        return token;
    });
    raw = sqEscapeHtml(raw).replace(/\r?\n/g, "<br>");
    for (var i = 0; i < images.length; i++) raw = raw.replace("__SQ_EMOJI_" + i + "__", images[i]);
    return raw;
}

function sqFormatTime(value) {
    var time = Number(value || 0);
    if (!time) return "";
    try { return sqJava.call(this).timeFormatUTC(time, "yyyy-MM-dd HH:mm", 28800000); } catch(e) { return ""; }
}

function sqReplyHtml(reply) {
    var name = sqEscapeHtml(reply && reply.nickname || "书友");
    var target = reply && reply.repliedUserNickname ? " 回复 " + sqEscapeHtml(reply.repliedUserNickname) : "";
    return '<div class="reply"><b>' + name + '</b>' + target + '：' + sqRichText(reply) + '</div>';
}

var _sqReplyDomSeq = 0;
function sqCommentCard(comment) {
    comment = comment || {};
    var avatar = String(comment.userPhoto || "");
    var replyData = comment.replies || {};
    var replies = sqList(replyData.commentList);
    var replyHtml = "";
    for (var i = 0; i < replies.length; i++) replyHtml += sqReplyHtml(replies[i]);
    var badges = comment.isAuthor ? '<span class="badge">作者</span>' : "";
    if (comment.fanCard && comment.fanCard.levelName) badges += '<span class="badge muted">' + sqEscapeHtml(comment.fanCard.levelName) + '</span>';

    var replyNum = Number(comment.replyNum || 0);
    var nextIndex = replyData.nextItemIndex;
    var hasMore = replyNum > replies.length && nextIndex !== null && nextIndex !== undefined && String(nextIndex) !== "";
    var safeMid = String(comment.mid || "comment").replace(/[^A-Za-z0-9_-]/g, "_");
    var replyTarget = "sq_replies_" + safeMid + "_" + (_sqReplyDomSeq++);
    var moreButton = hasMore
        ? '<button class="reply-more" type="button" data-target="' + replyTarget + '" data-mid="' + sqEscapeHtml(comment.mid || "") + '" data-cursor="' + sqEscapeHtml(nextIndex) + '" data-author="' + sqEscapeHtml(comment.authorId || "0") + '" onclick="sqLoadReplies(this)">展开更多回复</button>'
        : "";

    return '<article class="comment">' +
        '<div class="author">' + (avatar ? '<img class="avatar" src="' + sqEscapeHtml(avatar) + '">' : '<span class="avatar fallback"></span>') +
        '<div class="identity"><div><b>' + sqEscapeHtml(comment.nickname || "书友") + '</b>' + badges + '</div><time>' + sqFormatTime.call(this, comment.pubTime) + '</time></div>' +
        '<span class="likes">赞 ' + Number(comment.likes || 0) + '</span></div>' +
        '<div class="text">' + sqRichText(comment) + '</div>' +
        ((replyHtml || moreButton) ? '<div class="replies"><div id="' + replyTarget + '">' + replyHtml + '</div>' + moreButton + '</div>' : '') +
        '</article>';
}

function sqCards(list) {
    list = sqList(list);
    if (!list.length) return '<div class="empty">暂无评论</div>';
    var html = "";
    for (var i = 0; i < list.length; i++) html += sqCommentCard.call(this, list[i]);
    return html;
}

function sqBrowserConfig() {
    var cfg = sqCommentConfig.call(this);
    var height = Number(cfg.height || 80);
    if (height > 1) height = height / 100;
    if (!(height > 0 && height <= 1)) height = 0.8;
    return {
        state: 4,
        isHideable: true,
        heightPercentage: height,
        expandedCornersRadius: 16,
        dismissOnTouchOutside: true,
        widthPercentage: 1.0,
        maxWidth: -1,
        skipCollapsed: true,
        hardwareAccelerated: true,
        webViewInitialScale: 100
