var SQ_TTS_VOICE_REFRESHED = {};
function sqRefreshTtsVoices(currentBookId, force) {
  var id = String(currentBookId || "").trim();
  if (!id) return [];
  var storedId = "";
  var storedKeys = "";
  try {
    storedId = String(source.get("sqTtsVoiceBookId") || "").trim();
    storedKeys = String(source.get("sqTtsVoiceKeys") || "").trim();
  } catch (eStoredVoices) {}
  if (!force && storedId == id && storedKeys) {
    return storedKeys.split(",").filter(Boolean);
  }
  if (!force && SQ_TTS_VOICE_REFRESHED[id]) return [];
  SQ_TTS_VOICE_REFRESHED[id] = true;
  try {
    var raw = java.ajax(GetUrl("/webapi/bcspub/openapi/book/info", "bookId=" + id));
    var obj = JSON.parse(String(raw || "{}"));
    var data = obj && obj.data || {};
    var voices = Array.isArray(data.ttsSpeakerInfos) ? data.ttsSpeakerInfos :
      (data.bookInfo && Array.isArray(data.bookInfo.ttsSpeakerInfos) ? data.bookInfo.ttsSpeakerInfos : []);
    voices = voices.filter(function (v) { return String(v && v.speakerKey || "").trim(); });
    var keys = voices.map(function (v) { return String(v.speakerKey || "").trim(); });
    var names = voices.map(function (v) { return String(v.speakerName || v.speakerKey || "").trim(); });
    source.put("sqTtsVoiceBookId", id);
    source.put("sqTtsAvailable", keys.length ? "1" : "0");
    source.put("sqTtsVoiceKeys", keys.join(","));
    source.put("sqTtsVoiceNames", names.join("、"));
    return keys;
  } catch (eRefreshVoices) {
    return [];
  }
}

// Select a voice that the current book actually advertises. Composite or
// stale IDs such as multi_role must not be sent when the book exposes only
// individual speakers.
sqTtsSpeaker = function (currentBookId) {
  var selected = "";
  try { selected = String(source.get("sqTtsSpeaker") || "").trim(); } catch (eSelected) {}
  if (!selected) {
    try { selected = String(sqTtsSetting("自定义音色ID", "") || "").trim(); } catch (eCustom) {}
  }
  var hadExplicitSelection = !!selected;
  var refreshedKeys = sqRefreshTtsVoices(currentBookId);
  var rawKeys = "";
  try { rawKeys = String(source.get("sqTtsVoiceKeys") || "").trim(); } catch (eKeys) {}
  try {
    var voiceBookId = String(source.get("sqTtsVoiceBookId") || "").trim();
    if (currentBookId && voiceBookId && voiceBookId != String(currentBookId)) rawKeys = "";
  } catch (eVoiceBook) {}
  var keys = rawKeys ? rawKeys.split(",").map(function (key) { return String(key || "").trim(); }).filter(Boolean) : refreshedKeys;
  if (keys.length) {
    if (selected && keys.indexOf(selected) >= 0) return selected;
    var fallback = keys[0];
    try {
      source.put("sqTtsSpeaker", fallback);
      var noticeKey = "sqTtsToneFallbackNotice";
      var lastNotice = String(source.get(noticeKey) || "");
      var currentNotice = String(currentBookId || "") + ":" + fallback;
      if (lastNotice != currentNotice) {
        var names = String(source.get("sqTtsVoiceNames") || "").split("、");
        var fallbackName = names[0] || fallback;
        java.longToast((hadExplicitSelection ? "当前音色不存在或本书不支持" : "未设置听书音色") +
          "，已自动切换为本书第一个支持音色：" + fallbackName);
        source.put(noticeKey, currentNotice);
      }
    } catch (eFallback) {}
    return fallback;
  }
  return selected || "multi_role";
};
sqTtsAudioUrl = function (bookId, chapterId, speaker) {
  var actualSpeaker = String(speaker || "").trim() || sqTtsSpeaker(String(bookId));
  var params = "bookId=" + bookId +
    "&chapterIds=" + chapterId +
    "&isDownload=0&getAllUrl=&appVer=12.6.5.263&rType=1&orderSpeakerList=" + actualSpeaker;
  return SqTtsGetUrl("/api/bcspub/andapi/tts/download/v2", params);
