function sqListenDiscovery(channel, section, requestedPage, refresh) {
  var channelKey = channel == "female" ? "female" : (channel == "male" ? "male" : "default");
  var sectionKey = section == "hot" ? "hot" : (section == "recommend" ? "recommend" : "multi");
  var books = SQ_LISTEN_POOLS[channelKey] && SQ_LISTEN_POOLS[channelKey][sectionKey] || [];
  if (!books.length) return "[]";
  var pageSize = sectionKey == "hot" ? 4 : (sectionKey == "recommend" ? 10 : 8);
  var current = Math.max(1, Number(requestedPage) || 1);
  if (refresh) {
    var counterKey = "sqListenRefresh_" + channelKey + "_" + sectionKey;
    var counter = 0;
    try { counter = Number(source.get(counterKey) || 0); } catch (eCounter) {}
    current = counter + 1;
    try { source.put(counterKey, String(current)); } catch (eSaveCounter) {}
  }
  var start = ((current - 1) * pageSize) % books.length;
  var result = [];
  for (var i = 0; i < pageSize && i < books.length; i++) {
    result.push(books[(start + i) % books.length]);
  }
  return JSON.stringify(result);
}


