  applyTtsMeta(result);
  if (!bookId || !chapterId) {
    try {
      var jsonAt = base.indexOf("{");
      var info = jsonAt >= 0 ? JSON.parse(base.substring(jsonAt)) : {};
      bookId = bookId || String(info.bookId || "");
      chapterId = chapterId || String(info.chapterId || "");
    } catch (eInfo) {}
  }
  if (!chapterId) {
    var rawResult = String(result || "").trim();
    if (/^\d+$/.test(rawResult)) chapterId = rawResult;
  }
  if (!chapterId) {
    try {
      var dataMatch = base.match(/^data:;base64,([^,]+)/i);
      if (dataMatch) chapterId = String(java.base64Decode(dataMatch[1]) || "").trim();
    } catch (eDecode) {}
  }
  if (!bookId) {
    try { bookId = String(java.get("sqCurrentBookId") || ""); } catch (eBookFallback) {}
  }
  if (!chapterId) {
    try { chapterId = String(java.get("sqCurrentChapterId") || ""); } catch (eChapterFallback) {}
  }
  if (!bookId || !chapterId) {
    try { java.longToast("听书章节参数缺失：bookId=" + bookId + "，chapterId=" + chapterId + "，请刷新目录"); } catch (_) {}
    return "";
  }
  function sqBoundLoginValue(key) {
    try {
      var map = source.getLoginInfoMap();
      var value = map && (map.get ? map.get(key) : map[key]);
      return value == null ? "" : String(value).trim();
    } catch (eLoginValue) { return ""; }
  }
  function sqBoundSpeaker() {
    var value = "";
    try { value = String(source.get("sqTtsSpeaker") || "").trim(); } catch (eStoredTone) {}
    if (!value) value = sqBoundLoginValue("情感音色ID");
    if (!value) {
      var labeled = sqBoundLoginValue("情感音色");
      var matched = labeled.match(/\|\s*([A-Za-z0-9_\-]+)\s*$/);
      if (matched) value = matched[1];
    }
    if (!value) value = sqBoundLoginValue("自定义音色ID");
    return value || "multi_role";
  }
  function sqRefreshBoundTtsVoices(currentBookId) {
    var id = String(currentBookId || "").trim();
    if (!id) return [];
    try {
      var raw = java.ajax(SqTtsGetUrl("/webapi/bcspub/openapi/book/info", "bookId=" + id));
      var obj = JSON.parse(String(raw || "{}"));
      var data = obj && obj.data || {};
      var voices = Array.isArray(data.ttsSpeakerInfos) ? data.ttsSpeakerInfos :
        (data.bookInfo && Array.isArray(data.bookInfo.ttsSpeakerInfos) ? data.bookInfo.ttsSpeakerInfos : []);
      voices = voices.filter(function (voice) {
        return String(voice && voice.speakerKey || "").trim();
      });
      var keys = voices.map(function (voice) { return String(voice.speakerKey).trim(); });
      var names = voices.map(function (voice) {
        return String(voice.speakerName || voice.speakerKey || "").trim();
      });
      source.put("sqTtsVoiceBookId", id);
      source.put("sqTtsAvailable", keys.length ? "1" : "0");
      source.put("sqTtsVoiceKeys", keys.join(","));
      source.put("sqTtsVoiceNames", names.join("、"));
      source.put("sqTtsVoiceKeys@" + id, keys.join(","));
      source.put("sqTtsVoiceNames@" + id, names.join("、"));
      return keys;
    } catch (eRefreshVoices) { return []; }
  }
  var requestedSpeaker = sqBoundSpeaker();
  var raw;
  try { raw = java.ajax(sqTtsAudioUrl(bookId, chapterId, requestedSpeaker)); }
  catch (eRequest) {
    try { java.longToast("书旗TTS请求失败：" + eRequest); } catch (_) {}
    return "";
  }
  var obj;
  try { obj = JSON.parse(String(raw || "{}")); }
  catch (eParse) {
    try { java.longToast("书旗TTS响应解析失败"); } catch (_) {}
    return "";
  }
  var item = obj.data && obj.data.audioInfo && obj.data.audioInfo[0];
  var audioUrl = item && item.contents && item.contents.audioUrl;
  if (!audioUrl && item && item.title) audioUrl = item.title.audioUrl;
  if (!audioUrl) {
    try {
      var fallbackKeys = sqRefreshBoundTtsVoices(bookId);
      var fallbackSpeaker = fallbackKeys && fallbackKeys.length ? String(fallbackKeys[0] || "") : "";
      if (fallbackSpeaker && fallbackSpeaker != requestedSpeaker) {
        var retryRaw = java.ajax(sqTtsAudioUrl(bookId, chapterId, fallbackSpeaker));
        var retryObj = JSON.parse(String(retryRaw || "{}"));
        var retryItem = retryObj.data && retryObj.data.audioInfo && retryObj.data.audioInfo[0];
        var retryAudioUrl = retryItem && retryItem.contents && retryItem.contents.audioUrl;
        if (!retryAudioUrl && retryItem && retryItem.title) retryAudioUrl = retryItem.title.audioUrl;
        if (retryAudioUrl) {
          source.put("sqTtsSpeaker", fallbackSpeaker);
          source.put("sqTtsToneUpdatedAt", String(Date.now()));
          var fallbackNames = String(source.get("sqTtsVoiceNames") || "").split("、");
          java.longToast("所选音色无可用音频，已自动使用本书第一个支持音色：" +
            (fallbackNames[0] || fallbackSpeaker));
          return String(retryAudioUrl);
        }
        obj = retryObj;
      }
    } catch (eVoiceRetry) {}
  }
  if (!audioUrl) {
    try { java.longToast("本书当前章节没有可用的书旗TTS音频"); } catch (_) {}
    return "";
  }
  return String(audioUrl);
}).call(this);

